1	import fs from 'fs';
2	import path from 'path';
3	import { loadConfig } from './config';
4	import { SSGEngine, findMarkdownFiles } from './engine';
5	import { PluginContext } from './plugin';
6	import { Page } from './types';
7	
8	export { findMarkdownFiles };
9	
10	export interface BuildOptions {
11	  contentDir: string;
12	  outputDir: string;
13	  templatesDir?: string;
14	}
15	
16	export interface BuildResult {
17	  pages: Page[];
18	  outputDir: string;
19	}
20	
21	export function defaultTemplatesDir(): string {
22	  return path.resolve(process.cwd(), 'templates');
23	}
24	
25	export function buildPage(contentDir: string, filename: string, templatesDir: string = defaultTemplatesDir()): Page {
26	  const engine = new SSGEngine(loadConfig(process.cwd()).plugins);
27	  const ctx: PluginContext = { contentDir, templatesDir };
28	  return engine.buildFile(contentDir, filename, ctx);
29	}
30	
31	/**
32	 * Runs a full build pass through the plugin pipeline and writes the
33	 * resulting pages to `ctx.outputDir`. Shared by the one-shot `build()` below
34	 * and by the dev server, which reruns it on every watched file change using
35	 * the same engine instance (so plugins like the dev server's own reload
36	 * broadcast fire on every pass).
37	 */
38	export function buildAndWrite(engine: SSGEngine, ctx: PluginContext): Page[] {
39	  const outputDir = ctx.outputDir;
40	  if (!outputDir) {
41	    throw new Error('outputDir is required to write build output');
42	  }
43	  fs.mkdirSync(outputDir, { recursive: true });
44	  const pages = engine.runBuild(ctx);
45	  for (const page of pages) {
46	    fs.writeFileSync(path.join(outputDir, page.outputPath), page.html, 'utf-8');
47	  }
48	  return pages;
49	}
50	
51	export function build(options: BuildOptions): BuildResult {
52	  const { contentDir, outputDir, templatesDir = defaultTemplatesDir() } = options;
53	  const engine = new SSGEngine(loadConfig(process.cwd()).plugins);
54	  const ctx: PluginContext = { contentDir, outputDir, templatesDir };
55	  const pages = buildAndWrite(engine, ctx);
56	  return { pages, outputDir };
57	}
