1	import fs from 'fs';
2	import path from 'path';
3	import { parseFrontmatter } from './frontmatter';
4	import { Page } from './types';
5	import { Plugin, PluginContext, PageDraft } from './plugin';
6	
7	function slugify(filename: string): string {
8	  return filename.replace(/\.md$/i, '');
9	}
10	
11	function normalizeTags(tags: unknown): string[] {
12	  if (Array.isArray(tags)) return tags.map((tag) => String(tag));
13	  if (typeof tags === 'string' && tags.length > 0) return [tags];
14	  return [];
15	}
16	
17	export function findMarkdownFiles(contentDir: string): string[] {
18	  if (!fs.existsSync(contentDir)) {
19	    throw new Error(`Content directory not found: ${contentDir}`);
20	  }
21	  return fs
22	    .readdirSync(contentDir)
23	    .filter((file) => file.toLowerCase().endsWith('.md'))
24	    .sort();
25	}
26	
27	function makeDraft(contentDir: string, filename: string): PageDraft {
28	  const filePath = path.join(contentDir, filename);
29	  const raw = fs.readFileSync(filePath, 'utf-8');
30	  const { data, content } = parseFrontmatter(raw);
31	  const slug = slugify(filename);
32	  const title = typeof data.title === 'string' && data.title.length > 0 ? data.title : slug;
33	  const date = typeof data.date === 'string' ? data.date : undefined;
34	  const tags = normalizeTags(data.tags);
35	  const outputPath = `${slug}.html`;
36	  const template =
37	    typeof data.template === 'string' && data.template.trim().length > 0 ? data.template.trim() : 'default';
38	  return { slug, filename, data, content, title, date, tags, template, outputPath, body: '', html: '' };
39	}
40	
41	function toPage(draft: PageDraft): Page {
42	  return {
43	    slug: draft.slug,
44	    title: draft.title,
45	    date: draft.date,
46	    tags: draft.tags,
47	    html: draft.html,
48	    outputPath: draft.outputPath,
49	    template: draft.template,
50	  };
51	}
52	
53	/**
54	 * Orchestrates the plugin pipeline. `onStart`/`onEnd` bracket the engine's
55	 * whole lifetime (e.g. a dev server's process); `beforeBuild`/`onFile`/
56	 * `afterBuild` run once per build pass and stay fully synchronous so the
57	 * public `buildPage`/`build` API can remain synchronous too.
58	 */
59	export class SSGEngine {
60	  constructor(private readonly plugins: Plugin[]) {}
61	
62	  async start(ctx: PluginContext): Promise<void> {
63	    for (const plugin of this.plugins) {
64	      await plugin.onStart?.(ctx);
65	    }
66	  }
67	
68	  async end(ctx: PluginContext): Promise<void> {
69	    for (const plugin of this.plugins) {
70	      await plugin.onEnd?.(ctx);
71	    }
72	  }
73	
74	  buildFile(contentDir: string, filename: string, ctx: PluginContext): Page {
75	    const draft = makeDraft(contentDir, filename);
76	    for (const plugin of this.plugins) {
77	      plugin.onFile?.(draft, ctx);
78	    }
79	    return toPage(draft);
80	  }
81	
82	  runBuild(ctx: PluginContext): Page[] {
83	    for (const plugin of this.plugins) {
84	      plugin.beforeBuild?.(ctx);
85	    }
86	    const files = findMarkdownFiles(ctx.contentDir);
87	    const pages = files.map((file) => this.buildFile(ctx.contentDir, file, ctx));
88	    for (const plugin of this.plugins) {
89	      plugin.afterBuild?.(pages, ctx);
90	    }
91	    return pages;
92	  }
93	}
