4	import { build } from './build';
5	import { startServer } from './serve';
6	
7	const program = new Command();
8	
9	program.name('ssg').description('A minimal static site generator');
10	
11	program
12	  .command('build')
13	  .description('Generate the static site')
14	  .option('--content <dir>', 'content directory', './content')
15	  .option('--output <dir>', 'output directory', './dist')
16	  .option('--templates <dir>', 'templates directory', './templates')
17	  .action((opts: { content: string; output: string; templates: string }) => {
18	    const contentDir = path.resolve(process.cwd(), opts.content);
19	    const outputDir = path.resolve(process.cwd(), opts.output);
20	    const templatesDir = path.resolve(process.cwd(), opts.templates);
21	    const result = build({ contentDir, outputDir, templatesDir });
22	    console.log(`Built ${result.pages.length} page(s) into ${outputDir}`);
23	  });
24	
25	program
26	  .command('serve')
27	  .description('Start a live-reload development server')
28	  .option('--content <dir>', 'content directory', './content')
29	  .option('--output <dir>', 'output directory', './dist')
30	  .option('--templates <dir>', 'templates directory', './templates')
31	  .option('--port <port>', 'port to serve on', '3000')
32	  .action(async (opts: { content: string; output: string; templates: string; port: string }) => {
33	    const contentDir = path.resolve(process.cwd(), opts.content);
34	    const outputDir = path.resolve(process.cwd(), opts.output);
35	    const templatesDir = path.resolve(process.cwd(), opts.templates);
36	    const port = parseInt(opts.port, 10);
37	    const server = await startServer({ contentDir, outputDir, templatesDir, port });
38	    console.log(`Dev server running at http://localhost:${server.port}`);
39	  });
40	
41	if (require.main === module) {
42	  program.parse(process.argv);
43	}
44	
45	export { program };
