1	import fs from 'fs';
2	import path from 'path';
3	import { Plugin } from './plugin';
4	import { markdownPlugin } from '../plugins/markdown-plugin';
5	import { templatePlugin } from '../plugins/template-plugin';
6	
7	export interface SSGConfig {
8	  plugins: Plugin[];
9	}
10	
11	const DEFAULT_CONFIG_FILE = 'ssg.config.ts';
12	
13	function defaultPlugins(): Plugin[] {
14	  return [markdownPlugin(), templatePlugin()];
15	}
16	
17	/**
18	 * Requires a `.ts` config file. Under ts-jest/ts-node (as in this project's
19	 * own tests and `npm start`) a TypeScript require hook is already active, so
20	 * this succeeds directly. Under the plain compiled CLI (`dist-bin/cli.js`),
21	 * Node has no such hook, so the first attempt throws a SyntaxError on the
22	 * raw `import` syntax; in that case we lazily register ts-node and retry.
23	 */
24	function requireConfigModule(configPath: string): unknown {
25	  try {
26	    return require(configPath);
27	  } catch (err) {
28	    if (!(configPath.endsWith('.ts') && err instanceof SyntaxError)) {
29	      throw err;
30	    }
31	    require('ts-node/register/transpile-only');
32	    return require(configPath);
33	  }
34	}
35	
36	/**
37	 * Loads the build-time plugin pipeline from `ssg.config.ts` in `cwd`. Falls
38	 * back to the built-in markdown + template plugins when no config file is
39	 * present, when it doesn't export a plugin list, or when its TypeScript
40	 * source can't be loaded (e.g. ts-node isn't installed), so `ssg build`
41	 * keeps working without any project scaffolding.
42	 */
43	export function loadConfig(cwd: string, configFile: string = DEFAULT_CONFIG_FILE): SSGConfig {
44	  const configPath = path.resolve(cwd, configFile);
45	  if (!fs.existsSync(configPath)) {
46	    return { plugins: defaultPlugins() };
47	  }
48	
49	  let required: unknown;
50	  try {
51	    required = requireConfigModule(configPath);
52	  } catch (err) {
53	    console.warn(
54	      `ssg: could not load ${configFile} (${err instanceof Error ? err.message : err}); using built-in plugins instead.`
55	    );
56	    return { plugins: defaultPlugins() };
57	  }
58	
59	  const config = (required as { default?: Partial<SSGConfig> } & Partial<SSGConfig>)?.default ?? required;
60	  const plugins = (config as Partial<SSGConfig> | undefined)?.plugins;
61	  return { plugins: Array.isArray(plugins) && plugins.length > 0 ? plugins : defaultPlugins() };
62	}
