1	import fs from 'fs';
2	import path from 'path';
3	import { Plugin } from '../src/plugin';
4	import { getTemplateEngine } from '../src/templates';
5	
6	/**
7	 * Wraps each page's rendered body in its Handlebars layout, and writes the
8	 * site index page once every file in a build pass has been processed.
9	 */
10	export function templatePlugin(): Plugin {
11	  return {
12	    name: 'template',
13	    onFile(page, ctx) {
14	      const engine = getTemplateEngine(ctx.templatesDir);
15	      page.html = engine.renderPage(
16	        { title: page.title, date: page.date, tags: page.tags, body: page.body },
17	        page.template
18	      );
19	    },
20	    afterBuild(pages, ctx) {
21	      if (!ctx.outputDir) return;
22	      const engine = getTemplateEngine(ctx.templatesDir);
23	      fs.writeFileSync(path.join(ctx.outputDir, 'index.html'), engine.renderIndex(pages), 'utf-8');
24	    },
25	  };
26	}
