7	
8	const DEFAULT_PORT = 3000;
9	const LIVE_RELOAD_PATH = '/__livereload';
10	const REBUILD_DEBOUNCE_MS = 100;
11	
12	const CONTENT_TYPES: Record<string, string> = {
13	  '.html': 'text/html; charset=utf-8',
14	  '.css': 'text/css; charset=utf-8',
15	  '.js': 'text/javascript; charset=utf-8',
16	  '.json': 'application/json; charset=utf-8',
17	  '.svg': 'image/svg+xml',
18	  '.png': 'image/png',
19	  '.jpg': 'image/jpeg',
20	  '.jpeg': 'image/jpeg',
21	  '.gif': 'image/gif',
22	  '.ico': 'image/x-icon',
23	  '.txt': 'text/plain; charset=utf-8',
24	};
25	
26	const LIVE_RELOAD_SCRIPT = `
27	<script>
28	(function () {
29	  var socket = new WebSocket('ws://' + location.host + '${LIVE_RELOAD_PATH}');
30	  socket.addEventListener('message', function (event) {
31	    if (event.data === 'reload') {
32	      location.reload();
33	    }
34	  });
35	})();
36	</script>
37	`;
38	
39	function injectLiveReload(html: string): string {
40	  if (html.includes('</body>')) {
41	    return html.replace('</body>', `${LIVE_RELOAD_SCRIPT}</body>`);
42	  }
43	  return html + LIVE_RELOAD_SCRIPT;
44	}
45	
46	function resolveRequestedFile(outputDir: string, urlPath: string): string | undefined {
47	  const decoded = decodeURIComponent(urlPath.split('?')[0] ?? '/');
48	  let relative = decoded === '/' ? '/index.html' : decoded;
49	  if (relative.endsWith('/')) relative += 'index.html';
50	
51	  const root = path.resolve(outputDir);
52	  const resolved = path.resolve(root, `.${relative}`);
53	  if (resolved !== root && !resolved.startsWith(root + path.sep)) {
54	    return undefined;
55	  }
56	  return resolved;
57	}
58	
59	function sendNotFound(res: http.ServerResponse): void {
60	  res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
61	  res.end('404 Not Found');
62	}
63	
64	function serveFile(outputDir: string, urlPath: string, res: http.ServerResponse): void {
65	  const filePath = resolveRequestedFile(outputDir, urlPath);
66	  if (!filePath || !fs.existsSync(filePath) || !fs.statSync(filePath).isFile()) {
67	    sendNotFound(res);
68	    return;
69	  }
70	
71	  const ext = path.extname(filePath).toLowerCase();
72	  const contentType = CONTENT_TYPES[ext] ?? 'application/octet-stream';
73	
74	  if (ext === '.html') {
75	    const html = fs.readFileSync(filePath, 'utf-8');
76	    res.writeHead(200, { 'Content-Type': contentType });
77	    res.end(injectLiveReload(html));
78	    return;
79	  }
80	
81	  res.writeHead(200, { 'Content-Type': contentType });
82	  fs.createReadStream(filePath).pipe(res);
83	}
84	
85	export interface DevServerPluginOptions {
86	  port?: number;
87	  /** Triggers a full build pass (via the owning SSGEngine); called on every watched file change. */
88	  rebuild: () => void;
89	}
90	
91	export interface DevServerPlugin extends Plugin {
92	  getPort(): number;
93	}
94	
95	/**
96	 * Serves the output directory over HTTP, watches content/templates for
97	 * changes, and notifies connected browsers over WebSocket after each
98	 * rebuild. `afterBuild` (run by the engine for every build pass, including
99	 * ones triggered by this plugin's own watcher) is what broadcasts reloads.
100	 */
101	export function devServerPlugin(options: DevServerPluginOptions): DevServerPlugin {
102	  const { rebuild, port = DEFAULT_PORT } = options;
103	  let httpServer: http.Server | undefined;
104	  let wss: WebSocketServer | undefined;
105	  let watcher: FSWatcher | undefined;
106	  let rebuildTimer: NodeJS.Timeout | undefined;
107	  let actualPort = port;
108	
109	  const broadcastReload = (): void => {
110	    if (!wss) return;
111	    for (const client of wss.clients) {
112	      if (client.readyState === WebSocket.OPEN) {
113	        client.send('reload');
114	      }
115	    }
116	  };
117	
118	  const scheduleRebuild = (): void => {
119	    if (rebuildTimer) clearTimeout(rebuildTimer);
120	    rebuildTimer = setTimeout(() => {
121	      rebuild();
122	    }, REBUILD_DEBOUNCE_MS);
123	  };
124	
125	  return {
126	    name: 'dev-server',
127	
128	    getPort: () => actualPort,
129	
130	    async onStart(ctx: PluginContext) {
131	      const outputDir = ctx.outputDir as string;
132	
133	      httpServer = http.createServer((req, res) => {
134	        serveFile(outputDir, req.url ?? '/', res);
135	      });
136	      wss = new WebSocketServer({ server: httpServer, path: LIVE_RELOAD_PATH });
137	
138	      watcher = chokidar.watch([ctx.contentDir, ctx.templatesDir], { ignoreInitial: true });
139	      watcher.on('add', scheduleRebuild);
140	      watcher.on('change', scheduleRebuild);
141	      watcher.on('unlink', scheduleRebuild);
142	
143	      const listening = new Promise<number>((resolve, reject) => {
144	        httpServer!.once('error', reject);
145	        httpServer!.listen(port, () => {
146	          httpServer!.removeListener('error', reject);
147	          const address = httpServer!.address();
148	          resolve(typeof address === 'object' && address ? address.port : port);
149	        });
150	      });
151	      const watcherReady = new Promise<void>((resolve) => watcher!.once('ready', resolve));
152	
153	      const [resolvedPort] = await Promise.all([listening, watcherReady]);
154	      actualPort = resolvedPort;
155	    },
156	
157	    afterBuild() {
158	      broadcastReload();
159	    },
160	
161	    async onEnd() {
162	      if (rebuildTimer) clearTimeout(rebuildTimer);
163	      if (watcher) await watcher.close();
164	      if (wss) {
165	        const socket = wss;
166	        await new Promise<void>((resolve) => socket.close(() => resolve()));
167	        for (const client of socket.clients) client.terminate();
168	      }
169	      if (httpServer) {
170	        const server = httpServer;
171	        await new Promise<void>((resolve, reject) => server.close((err) => (err ? reject(err) : resolve())));
172	      }
173	    },
174	  };
175	}
176

