24	export async function startServer(options: ServeOptions): Promise<DevServer> {
25	  const {
26	    contentDir,
27	    outputDir,
28	    templatesDir = defaultTemplatesDir(),
29	    port = DEFAULT_PORT,
30	  } = options;
31	
32	  const ctx: PluginContext = { contentDir, outputDir, templatesDir };
33	  const buildPlugins = loadConfig(process.cwd()).plugins;
34	
35	  let engine: SSGEngine;
